create function public.memocious_admin_workspace(sid uuid, page_num int default 1) returns jsonb language plpgsql security invoker set search_path='' as $$
begin
 perform memocious_private.assert_admin(sid);
 if page_num not between 1 and 10000 then raise exception 'Invalid page' using errcode='22023';end if;
 return jsonb_build_object('total',(select count(*) from memocious.products),'products',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'version',p.version,'name',p.name,'slug',p.slug,'pricePaise',p.price_paise,'maxPricePaise',p.max_price_paise,'description',p.description,'detail',p.detail,'materials',p.materials,'dimensions',p.dimensions,'colour',p.colour,'lead',p.lead_type,'leadDays',p.lead_days,'moq',p.moq,'enterprise',p.enterprise,'customizable',p.customizable,'featured',p.featured,'inStock',p.in_stock,'active',p.active,'deleted',p.deleted_at is not null,'publicationState',p.publication_state,'messageLimit',p.message_limit,'seoTitle',coalesce(p.seo_title,''),'seoDescription',coalesce(p.seo_description,''),'categories',(select coalesce(jsonb_agg(pc.category_id),'[]') from memocious.product_categories pc where pc.product_id=p.id),'occasions',(select coalesce(jsonb_agg(po.occasion_id),'[]') from memocious.product_occasions po where po.product_id=p.id),'images',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'alt',i.alt,'sortOrder',i.sort_order,'published',i.published_at is not null) order by i.sort_order,i.id),'[]') from memocious.product_images i where i.product_id=p.id),'options',(select coalesce(jsonb_agg(jsonb_build_object('kind',o.kind,'label',o.label,'required',o.required,'maxCount',coalesce(o.max_count,1),'values',(select coalesce(jsonb_agg(jsonb_build_object('label',v.label,'deltaPaise',v.delta_paise) order by v.sort_order,v.id),'[]') from memocious.option_values v where v.option_id=o.id and v.active)) order by o.sort_order,o.id),'[]') from memocious.product_options o where o.product_id=p.id and o.active)) order by p.updated_at desc,p.id),'[]') from (select * from memocious.products order by updated_at desc,id limit 24 offset (page_num-1)*24) p),
 'taxonomy',(select coalesce(jsonb_agg(item order by item->>'kind',(item->>'sortOrder')::int,item->>'slug'),'[]') from (select jsonb_build_object('kind','category','id',id,'version',version,'slug',slug,'label',label,'parentId',parent_id,'sortOrder',sort_order,'active',active) item from memocious.categories union all select jsonb_build_object('kind','occasion','id',id,'version',version,'slug',slug,'label',label,'parentId',parent_id,'sortOrder',sort_order,'active',active) from memocious.occasions) t),
 'settings',jsonb_build_object('brand',coalesce((select value#>>'{}' from memocious.site_settings where key='brand'),'Memocious'),'tagline',coalesce((select value#>>'{}' from memocious.site_settings where key='tagline'),''),'contactEmail',coalesce((select value#>>'{}' from memocious.site_settings where key='contact_email'),''),'whatsappNumber',(select value#>>'{}' from memocious.site_settings where key='whatsapp_number'),'requireLogin',coalesce((select value='true'::jsonb from memocious.site_settings where key='require_login'),false)));
end $$;
revoke execute on function public.memocious_admin_workspace(uuid,int) from public,anon,authenticated;grant execute on function public.memocious_admin_workspace(uuid,int) to service_role;
